#include <vector>
#include <queue>

class Solution {
public:
    double frogPosition(int n, std::vector<std::vector<int>>& edges, int t, int target) {
        if (n == 1) return 1.0;
        std::vector<std::vector<int>> adj(n + 1);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<double> prob(n + 1, 0.0);
        std::vector<bool> visited(n + 1, false);
        std::queue<std::pair<int, int>> q;
        q.push({1, 0});
        visited[1] = true;
        prob[1] = 1.0;
        while (!q.empty()) {
            auto [u, timeSpent] = q.front();
            q.pop();
            int unvisitedCount = 0;
            for (int v : adj[u]) {
                if (!visited[v]) unvisitedCount++;
            }
            if (u == target) {
                if (timeSpent == t || (timeSpent < t && unvisitedCount == 0)) return prob[u];
                return 0.0;
            }
            if (timeSpent < t && unvisitedCount > 0) {
                for (int v : adj[u]) {
                    if (!visited[v]) {
                        visited[v] = true;
                        prob[v] = prob[u] / unvisitedCount;
                        q.push({v, timeSpent + 1});
                    }
                }
            }
        }
        return 0.0;
    }
};

import java.util.*;

class Solution {
    public double frogPosition(int n, int[][] edges, int t, int target) {
        if (n == 1) return 1.0;
        List<List<Integer>> adj = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        double[] prob = new double[n + 1];
        boolean[] visited = new boolean[n + 1];
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{1, 0});
        visited[1] = true;
        prob[1] = 1.0;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int u = cur[0], timeSpent = cur[1];
            int unvisitedCount = 0;
            for (int v : adj.get(u)) {
                if (!visited[v]) unvisitedCount++;
            }
            if (u == target) {
                if (timeSpent == t || (timeSpent < t && unvisitedCount == 0)) return prob[u];
                return 0.0;
            }
            if (timeSpent < t && unvisitedCount > 0) {
                for (int v : adj.get(u)) {
                    if (!visited[v]) {
                        visited[v] = true;
                        prob[v] = prob[u] / unvisitedCount;
                        q.offer(new int[]{v, timeSpent + 1});
                    }
                }
            }
        }
        return 0.0;
    }
}

var frogPosition = function(n, edges, t, target) {
    if (n === 1) return 1.0;
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const prob = new Array(n + 1).fill(0.0);
    const visited = new Array(n + 1).fill(false);
    const q = [[1, 0]];
    visited[1] = true;
    prob[1] = 1.0;
    while (q.length > 0) {
        const [u, timeSpent] = q.shift();
        let unvisitedCount = 0;
        for (const v of adj[u]) {
            if (!visited[v]) unvisitedCount++;
        }
        if (u === target) {
            if (timeSpent === t || (timeSpent < t && unvisitedCount === 0)) return prob[u];
            return 0.0;
        }
        if (timeSpent < t && unvisitedCount > 0) {
